667	Halfedge_Mesh Halfedge_Mesh::copy() const {
668	
669		std::unordered_map< Vertex const *, VertexRef > vertex_map;
670		std::unordered_map< Edge const *, EdgeRef > edge_map;
671		std::unordered_map< Face const *, FaceRef > face_map;
672		std::unordered_map< Halfedge const *, HalfedgeRef > halfedge_map;
673	
674		Halfedge_Mesh mesh;
675	
676		//new mesh should also have the same next_id as this one:
677		mesh.next_id = next_id;
678	
679		// Copy geometry from the original mesh and create a map from
680		// pointers in the original mesh to those in the new mesh.
681		for (VertexCRef v = vertices.begin(); v != vertices.end(); v++) {
682			VertexRef vn = mesh.vertices.insert(mesh.vertices.end(), *v);
683			vertex_map[&*v] = vn;
684		}
685		for (EdgeCRef e = edges.begin(); e != edges.end(); e++) {
686			EdgeRef en = mesh.edges.insert(mesh.edges.end(), *e);
687			edge_map[&*e] = en;
688		}
689		for (FaceCRef f = faces.begin(); f != faces.end(); f++) {
690			FaceRef fn = mesh.faces.insert(mesh.faces.end(), *f);
691			face_map[&*f] = fn;
692		}
693		for (HalfedgeCRef h = halfedges.begin(); h != halfedges.end(); h++) {
694			HalfedgeRef hn = mesh.halfedges.insert(mesh.halfedges.end(), *h);
695			halfedge_map[&*h] = hn;
696		}
697	
698		// "Search and replace" old pointers with new ones.
699		for (HalfedgeRef he = mesh.halfedges.begin(); he != mesh.halfedges.end(); he++) {
700			he->next = halfedge_map.at(&*he->next);
701			he->twin = halfedge_map.at(&*he->twin);
702			he->vertex = vertex_map.at(&*he->vertex);
703			he->edge = edge_map.at(&*he->edge);
704			he->face = face_map.at(&*he->face);
705		}
706		for (VertexRef v = mesh.vertices.begin(); v != mesh.vertices.end(); v++) {
707			v->halfedge = halfedge_map.at(&*v->halfedge);
708		}
709		for (EdgeRef e = mesh.edges.begin(); e != mesh.edges.end(); e++) {
710			e->halfedge = halfedge_map.at(&*e->halfedge);
711		}
712		for (FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
713			f->halfedge = halfedge_map.at(&*f->halfedge);
714		}

